let language = "nl";
let breathInterval = null;
let breathTimeout = null;
let toastTimeout = null;
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const t = key => translations[language][key] || translations.nl[key] || key;
function showToast(message) {
  const toast = $("#toast");
  toast.textContent = message;
  toast.classList.add("show");
  clearTimeout(toastTimeout);
  toastTimeout = setTimeout(() => toast.classList.remove("show"), 2800);
}
function setView(view) {
  $$(".view").forEach(section => section.classList.toggle("active", section.id === `view-${view}`));
  $$(".nav-item[data-view]").forEach(button => button.classList.toggle("active", button.dataset.view === view));
  $("#welcome").hidden = view !== "home";
  const heading = $(`#view-${view} h2`);
  if (heading) heading.setAttribute("tabindex", "-1");
  if (heading) heading.focus({preventScroll:true});
  window.scrollTo({top:0,behavior:document.body.classList.contains("reduced-motion") ? "auto" : "smooth"});
}
function updateTaskCount() {
  const checked = $$('[data-task]').filter(input => input.checked).length;
  $("#task-count").textContent = `${checked} / 3`;
  $("#progress-fill").style.width = `${checked / 3 * 100}%`;
}
function applyLanguage(next) {
  language = next === "en" ? "en" : "nl";
  document.documentElement.lang = language;
  $$("[data-i18n]").forEach(el => { const key = el.dataset.i18n; if (translations[language][key]) el.textContent = translations[language][key]; });
  $$("[data-i18n-placeholder]").forEach(el => { const key = el.dataset.i18nPlaceholder; if (translations[language][key]) el.placeholder = translations[language][key]; });
  $$("[data-i18n-aria-label]").forEach(el => { const key = el.dataset.i18nAriaLabel; if (translations[language][key]) el.setAttribute("aria-label", translations[language][key]); });
  $("#language").value = language;
  $("#language-settings").value = language;
  $("#language").setAttribute("aria-label", t("language"));
  $("[data-complete-routine]").forEach(button => { const done = button.dataset.done === "true"; button.textContent = done ? t("routineMarkedDone") : t("routineMarkDone"); });
  $("#today-date").textContent = new Intl.DateTimeFormat(language === "nl" ? "nl-NL" : "en-GB", {weekday:"short",day:"numeric",month:"short"}).format(new Date());
  $("#task-status").textContent = "";
  $("#routine-status").textContent = "";
  $("[data-routine-step]").forEach(input => updateRoutineProgress(input.dataset.routineStep));
  $("#breath-word").textContent = t("ready");
  $("#breath-instruction").textContent = t("breathIntro");
}
$$("[data-view]").forEach(button => button.addEventListener("click", () => setView(button.dataset.view)));
$("#language").addEventListener("change", event => { applyLanguage(event.target.value); savePreferences(); });
$("#language-settings").addEventListener("change", event => { applyLanguage(event.target.value); savePreferences(); });
$$("[data-task]").forEach(input => input.addEventListener("change", () => {
  updateTaskCount();
  const checked = $$("[data-task]").filter(item => item.checked).length;
  $("#task-status").textContent = checked === 3 ? t("allTasksDone") : input.checked ? t("taskDone") : "";
}));
function updateRoutineProgress(routine) {
  const steps = $$("[data-routine-step]").filter(input => input.dataset.routineStep === routine);
  const done = steps.filter(input => input.checked).length;
  const progress = $(`[data-routine-progress="${routine}"]`);
  if (progress) progress.textContent = t("routineProgress").replace("{done}", String(done)).replace("{total}", String(steps.length));
  const button = $(`[data-complete-routine="${routine}"]`);
  if (button) {
    const complete = steps.length > 0 && done === steps.length;
    button.dataset.done = String(complete);
    button.setAttribute("aria-pressed", String(complete));
    button.textContent = complete ? t("routineMarkedDone") : t("routineMarkDone");
    button.classList.toggle("primary-button", complete);
    button.classList.toggle("secondary-button", !complete);
  }
}
$$("[data-routine-step]").forEach(input => input.addEventListener("change", () => {
  updateRoutineProgress(input.dataset.routineStep);
  $("#routine-status").textContent = input.checked ? t("routineStepDone") : "";
}));
$$("[data-complete-routine]").forEach(button => button.addEventListener("click", () => {
  const routine = button.dataset.completeRoutine;
  const steps = $$("[data-routine-step]").filter(input => input.dataset.routineStep === routine);
  const complete = steps.length > 0 && steps.every(input => input.checked);
  steps.forEach(input => { input.checked = !complete; });
  updateRoutineProgress(routine);
  $("#routine-status").textContent = !complete ? t("routineDone") : "";
}));

function stopBreathing(announce = true) {
  clearInterval(breathInterval);
  clearTimeout(breathTimeout);
  breathInterval = null;
  breathTimeout = null;
  $("#breathing-orb").classList.remove("breathe-in", "breathe-out");
  $("#breath-word").textContent = t("ready");
  $("#breath-instruction").textContent = announce ? t("breathingStopped") : t("breathIntro");
}
function breathingPhase(inhaling) {
  $("#breathing-orb").classList.toggle("breathe-in", inhaling);
  $("#breathing-orb").classList.toggle("breathe-out", !inhaling);
  $("#breath-word").textContent = inhaling ? t("breathingIn") : t("breathingOut");
  $("#breath-instruction").textContent = inhaling ? t("breathingIn") : t("breathingOut");
}
$("#breath-start").addEventListener("click", () => {
  stopBreathing(false);
  let inhale = true;
  breathingPhase(inhale);
  breathInterval = setInterval(() => { inhale = !inhale; breathingPhase(inhale); }, 4000);
});
$("#breath-stop").addEventListener("click", () => stopBreathing(true));
const tips = {senses:"tipSenses",quiet:"tipQuiet",water:"tipWater"};
$$("[data-calm-tip]").forEach(button => button.addEventListener("click", () => { $("#calm-tip-text").textContent = t(tips[button.dataset.calmTip]); }));
const phrases = {break:"phraseBreakText",help:"phraseHelpText",slow:"phraseSlowText",no:"phraseNoText"};
$$("[data-phrase]").forEach(button => button.addEventListener("click", () => {
  $("#phrase-output").hidden = false;
  $("#phrase-output-text").textContent = t(phrases[button.dataset.phrase]);
  $("#phrase-output").scrollIntoView({behavior:document.body.classList.contains("reduced-motion") ? "auto" : "smooth",block:"nearest"});
  $("#close-phrase").focus();
}));
$("#close-phrase").addEventListener("click", () => { $("#phrase-output").hidden = true; });
$("#speak-phrase").addEventListener("click", () => {
  const phrase = $("#phrase-output-text").textContent;
  if (!("speechSynthesis" in window) || !("SpeechSynthesisUtterance" in window)) { showToast(t("readUnavailable")); return; }
  try {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(phrase);
    utterance.lang = language === "nl" ? "nl-NL" : "en-GB";
    window.speechSynthesis.speak(utterance);
  } catch { showToast(t("readError")); }
});
$("#clear-note").addEventListener("click", () => { $("#note-text").value = ""; $("#note-status").textContent = t("noteCleared"); $("#note-text").focus(); });

// In-memory drawing pad: nothing is stored or uploaded.
const sketchCanvas = $("#sketch-canvas");
const sketchContext = sketchCanvas.getContext("2d");
let sketchDrawing = false;
let sketchPointer = {x: sketchCanvas.width / 2, y: sketchCanvas.height / 2};
function sketchPoint(event) {
  const rect = sketchCanvas.getBoundingClientRect();
  return {
    x: (event.clientX - rect.left) * sketchCanvas.width / rect.width,
    y: (event.clientY - rect.top) * sketchCanvas.height / rect.height
  };
}
function drawSketchLine(from, to) {
  sketchContext.beginPath();
  sketchContext.moveTo(from.x, from.y);
  sketchContext.lineTo(to.x, to.y);
  sketchContext.strokeStyle = "#b9a7ff";
  sketchContext.lineWidth = Number($("#brush-size").value) * (sketchCanvas.width / sketchCanvas.getBoundingClientRect().width);
  sketchContext.lineCap = "round";
  sketchContext.lineJoin = "round";
  sketchContext.stroke();
}
sketchCanvas.addEventListener("pointerdown", event => {
  sketchDrawing = true;
  sketchPointer = sketchPoint(event);
  sketchCanvas.setPointerCapture?.(event.pointerId);
});
sketchCanvas.addEventListener("pointermove", event => {
  if (!sketchDrawing) return;
  const next = sketchPoint(event);
  drawSketchLine(sketchPointer, next);
  sketchPointer = next;
  $("#sketch-status").textContent = t("sketchDrawn");
});
function endSketchPointer() { sketchDrawing = false; }
sketchCanvas.addEventListener("pointerup", endSketchPointer);
sketchCanvas.addEventListener("pointercancel", endSketchPointer);
sketchCanvas.addEventListener("keydown", event => {
  const deltas = {ArrowUp:[0,-8],ArrowDown:[0,8],ArrowLeft:[-8,0],ArrowRight:[8,0]};
  const delta = deltas[event.key];
  if (!delta) return;
  event.preventDefault();
  const next = {
    x: Math.max(0, Math.min(sketchCanvas.width, sketchPointer.x + delta[0])),
    y: Math.max(0, Math.min(sketchCanvas.height, sketchPointer.y + delta[1]))
  };
  if (!event.shiftKey) drawSketchLine(sketchPointer, next);
  sketchPointer = next;
  $("#sketch-status").textContent = t("sketchDrawn");
});
$("#clear-sketch").addEventListener("click", () => {
  sketchContext.clearRect(0, 0, sketchCanvas.width, sketchCanvas.height);
  $("#sketch-status").textContent = t("sketchCleared");
  sketchCanvas.focus();
});
const preferenceKey = "project-n-01-preferences-v1";
function readPreferences() {
  try {
    const raw = localStorage.getItem(preferenceKey);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}
function savePreferences() {
  try {
    localStorage.setItem(preferenceKey, JSON.stringify({
      language,
      largeText: $("#large-text").checked,
      reducedMotion: $("#less-motion").checked,
      quietView: $("#quiet-view").checked
    }));
  } catch {
    // Preferences still work for this session if storage is unavailable.
  }
}
function applyPreferences() {
  const preferences = readPreferences();
  $("#large-text").checked = preferences.largeText === true;
  $("#less-motion").checked = preferences.reducedMotion === true;
  $("#quiet-view").checked = preferences.quietView === true;
  document.body.classList.toggle("large-text", $("#large-text").checked);
  document.body.classList.toggle("reduced-motion", $("#less-motion").checked);
  document.body.classList.toggle("quiet-view", $("#quiet-view").checked);
  applyLanguage(preferences.language === "en" ? "en" : "nl");
}
$("#large-text").addEventListener("change", event => {
  document.body.classList.toggle("large-text", event.target.checked);
  savePreferences();
});
$("#less-motion").addEventListener("change", event => {
  document.body.classList.toggle("reduced-motion", event.target.checked);
  savePreferences();
});
$("#quiet-view").addEventListener("change", event => {
  document.body.classList.toggle("quiet-view", event.target.checked);
  savePreferences();
});
$("#today-date").textContent = new Intl.DateTimeFormat("nl-NL", {weekday:"short",day:"numeric",month:"short"}).format(new Date());
updateTaskCount();
applyPreferences();

// Offline support is enabled only on secure origins or localhost.
if ("serviceWorker" in navigator && (location.protocol === "https:" || location.hostname === "localhost" || location.hostname === "127.0.0.1")) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("/service-worker.js").catch(() => {
      // The prototype remains usable if service workers are unavailable.
    });
  }, { once: true });
}
